arguments.command:
sed -i '$d' tests/book_test.sh && cat >> tests/book_test.sh <<'EOF'

# overlap rules (ROOM-12)
f=$(mktemp); rm -f "$f"
BOOKINGS=$f bash bin/book A 0900 1000 first >/dev/null
BOOKINGS=$f bash bin/book A 0930 1030 overlap >/dev/null 2>&1 && { echo "overlap accepted"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0900 before >/dev/null 2>&1 || { echo "end==start rejected"; fail=1; }
BOOKINGS=$f bash bin/book A 1000 1100 after >/dev/null 2>&1 || { echo "start==end rejected"; fail=1; }
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null 2>&1 || { echo "other room rejected"; fail=1; }
BOOKINGS=$f bash bin/book A 0850 1110 cover >/dev/null 2>&1 && { echo "cover accepted"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "rejected booking was written"; fail=1; }
rm -f "$f"
exit $fail
EOF
tail -14 tests/book_test.sh | head -4; bash tests/book_test.sh; echo rc=$?

