#!/bin/bash
fail=0
f=$(mktemp)
out=$(BOOKINGS=$f bash bin/book A 0900 1000 standup)
[ "$out" = "booked A 0900-1000" ] || { echo "book output"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "book appends"; fail=1; }
rm -f "$f"

# ROOM-12: overlapping bookings in the same room are rejected
f=$(mktemp)
BOOKINGS=$f bash bin/book A 0900 1000 standup >/dev/null
for t in "0930 1030" "0830 0930" "0915 0945" "0800 1100" "0900 1000"; do
  set -- $t
  before=$(cat "$f")
  BOOKINGS=$f bash bin/book A "$1" "$2" dup >/dev/null 2>&1 && { echo "overlap $1-$2 accepted"; fail=1; }
  [ "$(cat "$f")" = "$before" ] || { echo "overlap $1-$2 wrote file"; fail=1; }
done
for t in "A 1000 1100" "A 0800 0900" "B 0900 1000"; do
  set -- $t
  BOOKINGS=$f bash bin/book "$1" "$2" "$3" ok >/dev/null 2>&1 || { echo "valid $t rejected"; fail=1; }
done
[ "$(wc -l < "$f")" -eq 4 ] || { echo "valid bookings count"; fail=1; }
rm -f "$f"
exit $fail

